<template><section><div class="zj-summary"><div><h3>维保工作登记</h3><p class="zj-sub">按月度、季度或年度计划逐条登记，各项状态独立维护；修改后点击页面下方保存登记信息。</p></div><el-button v-if="!disabled" type="primary" @click="add">添加记录</el-button></div><el-table :data="entries" empty-text="暂无登记记录，点击添加记录开始填写"><el-table-column label="月份" width="155"><template #default="{row}"><el-date-picker v-model="row.period" type="month" value-format="YYYY-MM" style="width:135px" :disabled="disabled"/></template></el-table-column><el-table-column label="计划类别" width="145"><template #default="{row}"><el-select v-model="row.planType" :disabled="disabled"><el-option v-for="(label,key) in types" :key="key" :label="label" :value="key"/></el-select></template></el-table-column><el-table-column label="记录名称" min-width="240"><template #default="{row}"><el-input v-model="row.title" maxlength="200" placeholder="例如：2026年11月 月度计划" :disabled="disabled"/></template></el-table-column><el-table-column v-for="[key,label] in flags" :key="key" :label="label" width="95"><template #default="{row}"><el-checkbox v-model="row[key]" :disabled="disabled" :aria-label="row.title+' '+label"/></template></el-table-column><el-table-column v-if="!disabled" label="操作" width="80"><template #default="{row}"><el-button link type="danger" @click="remove(row)">删除</el-button></template></el-table-column></el-table><el-collapse v-if="Object.keys(legacy).length" style="margin-top:20px"><el-collapse-item title="原登记信息（保留备查）"><pre style="white-space:pre-wrap">{{JSON.stringify(legacy,null,2)}}</pre></el-collapse-item></el-collapse></section></template>
<script setup>
import {ElMessageBox} from 'element-plus'
const model=defineModel({type:Object,required:true});defineProps({disabled:Boolean});const types={monthly:'月度计划',quarterly:'季度计划',annual:'年度计划'},flags=[['issued','是否下发'],['reviewed','是否审核'],['approved','是否通过'],['filed','是否备案'],['printed','是否打印']]
const entries=computed(()=>model.value.entries||[]),legacy=computed(()=>Object.fromEntries(Object.entries(model.value).filter(([key,value])=>key!=='entries'&&value!=null&&value!==''&&value!=='unknown')))
function add(){const date=new Date(),period=`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}`;if(!model.value.entries)model.value.entries=[];model.value.entries.push({id:Array.from(crypto.getRandomValues(new Uint8Array(16)),n=>n.toString(16).padStart(2,'0')).join(''),period,planType:'monthly',title:`${date.getFullYear()}年${String(date.getMonth()+1).padStart(2,'0')}月 月度计划`,issued:false,reviewed:false,approved:false,filed:false,printed:false})}
async function remove(row){try{await ElMessageBox.confirm(`删除“${row.title}”？保存登记信息后生效。`);model.value.entries=model.value.entries.filter(x=>x.id!==row.id)}catch{}}
</script>
